                "timeout_seconds": {"type": "integer", "minimum": 1, "maximum": 3600},
                "scenarios": {
                  "type": "array", "uniqueItems": true,
                  "items": {
                    "type": "object", "additionalProperties": false,
                    "required": ["id", "description"],
                    "properties": {
                      "id": {"type": "string", "minLength": 1},
